import React from "react";
import { Meta, StoryObj } from "@storybook/react";
import Flight from "@material-design-icons/svg/filled/flight.svg?react";
import Inline from "../Inline";
import Stack from "../Stack";
import Chip from "./Chip";
import withDarkMode from "../../lib/utils/storybookDecorators";
import { Search } from "@airbus/icons/react";

const icons = {
  flight: <Flight />,
  search: <Search />,
  none: undefined,
};
const meta: Meta<typeof Chip> = {
  title: "Components/Chip",
  component: Chip,
  argTypes: {
    label: { control: { type: "text" } },
    type: { name: "string", required: false },
    size: {
      control: { type: "select", options: ["medium", "small", "xsmall"] },
    },
    icon: {
      options: Object.keys(icons),
      mapping: icons,
      control: {
        type: "select",
        labels: {
          Flight: "Flight",
          Search: "Search",
          None: "None",
        },
      },
      description: "An icon to display. The options provided here are for the purpose of example. Look at code to understand how to use icons.",
    },
  },
  args: {
    size: "small",
    variant: "default"
  },
  render: (args) => (
    <Inline spacing="2-x">
      <Chip label="Value" {...args} />
    </Inline>
  ),
} satisfies Meta<typeof Chip>;
export default meta;

type Story = StoryObj<typeof Chip>;

export const Basic: Story = {
  tags: ["visual-test"],
};

export const Variants: Story = {
  tags: ["visual-test"],
  render: () => {
    return (
      <Inline spacing="2-x">
        <Chip label="New" variant="info" />
        <Chip label="Approved" variant="success" />
        <Chip label="Pending" variant="warning" />
        <Chip label="Rejected" variant="error" />
      </Inline>
    );
  },
};

